/**
 * Weather Data Cache Service
 *
 * Implements intelligent caching for Open-Meteo API responses using IndexedDB.
 * Features:
 * - Stale-while-revalidate pattern
 * - Configurable TTL per data type
 * - Automatic cleanup of expired data
 * - 50MB storage limit with LRU eviction
 */
import { CACHE_CONFIG } from '../constants';
class WeatherCacheService {
    constructor() {
        this.dbName = 'SeaMeCache';
        this.storeName = 'weatherData';
        this.version = 1;
        this.db = null;
        this.maxSize = CACHE_CONFIG.MAX_SIZE_BYTES;
        // Cache TTL configurations
        this.TTL = {
            marine: CACHE_CONFIG.TTL.MARINE,
            forecast: CACHE_CONFIG.TTL.FORECAST,
            current: CACHE_CONFIG.TTL.CURRENT,
            multiModel: CACHE_CONFIG.TTL.MULTIMODEL,
            grib: CACHE_CONFIG.TTL.GRIB,
        };
        // Cache hit/miss tracking
        this.stats = {
            hits: 0,
            misses: 0,
        };
    }
    /**
     * Initialize IndexedDB connection
     */
    async openDB() {
        if (this.db)
            return this.db;
        return new Promise((resolve, reject) => {
            const request = indexedDB.open(this.dbName, this.version);
            request.onerror = () => reject(request.error);
            request.onsuccess = () => {
                this.db = request.result;
                resolve(this.db);
            };
            request.onupgradeneeded = (event) => {
                const db = event.target.result;
                // Create object store if it doesn't exist
                if (!db.objectStoreNames.contains(this.storeName)) {
                    const store = db.createObjectStore(this.storeName, { keyPath: 'key' });
                    store.createIndex('timestamp', 'timestamp', { unique: false });
                    store.createIndex('expiresAt', 'expiresAt', { unique: false });
                }
            };
        });
    }
    /**
     * Get data from cache
     */
    async get(key) {
        try {
            const db = await this.openDB();
            const tx = db.transaction(this.storeName, 'readonly');
            const store = tx.objectStore(this.storeName);
            return new Promise((resolve, reject) => {
                const request = store.get(key);
                request.onsuccess = () => {
                    const cached = request.result;
                    if (!cached) {
                        this.stats.misses++;
                        resolve(null);
                        return;
                    }
                    const now = Date.now();
                    // Check if expired
                    if (now > cached.expiresAt) {
                        this.stats.misses++;
                        // Delete expired entry
                        this.delete(key);
                        resolve(null);
                        return;
                    }
                    this.stats.hits++;
                    resolve(cached.data);
                };
                request.onerror = () => reject(request.error);
            });
        }
        catch (error) {
            console.error('Cache get error:', error);
            return null;
        }
    }
    /**
     * Set data in cache
     */
    async set(key, data, ttl) {
        try {
            const db = await this.openDB();
            const now = Date.now();
            // Calculate data size (rough estimate)
            const size = new Blob([JSON.stringify(data)]).size;
            // Ensure we have space
            await this.ensureSpace(size);
            const cached = {
                data,
                timestamp: now,
                expiresAt: now + ttl,
                size,
            };
            const tx = db.transaction(this.storeName, 'readwrite');
            const store = tx.objectStore(this.storeName);
            return new Promise((resolve, reject) => {
                const request = store.put({ key, ...cached });
                request.onsuccess = () => resolve();
                request.onerror = () => reject(request.error);
            });
        }
        catch (error) {
            console.error('Cache set error:', error);
        }
    }
    /**
     * Delete specific cache entry
     */
    async delete(key) {
        try {
            const db = await this.openDB();
            const tx = db.transaction(this.storeName, 'readwrite');
            const store = tx.objectStore(this.storeName);
            return new Promise((resolve, reject) => {
                const request = store.delete(key);
                request.onsuccess = () => resolve();
                request.onerror = () => reject(request.error);
            });
        }
        catch (error) {
            console.error('Cache delete error:', error);
        }
    }
    /**
     * Invalidate cache entries matching pattern
     */
    async invalidate(pattern) {
        try {
            const db = await this.openDB();
            const tx = db.transaction(this.storeName, 'readwrite');
            const store = tx.objectStore(this.storeName);
            return new Promise((resolve, reject) => {
                const request = store.openCursor();
                request.onsuccess = (event) => {
                    const cursor = event.target.result;
                    if (cursor) {
                        const key = cursor.value.key;
                        if (key.includes(pattern)) {
                            cursor.delete();
                        }
                        cursor.continue();
                    }
                    else {
                        resolve();
                    }
                };
                request.onerror = () => reject(request.error);
            });
        }
        catch (error) {
            console.error('Cache invalidate error:', error);
        }
    }
    /**
     * Clear all cache data
     */
    async clearAll() {
        try {
            const db = await this.openDB();
            const tx = db.transaction(this.storeName, 'readwrite');
            const store = tx.objectStore(this.storeName);
            return new Promise((resolve, reject) => {
                const request = store.clear();
                request.onsuccess = () => {
                    this.stats = { hits: 0, misses: 0 };
                    resolve();
                };
                request.onerror = () => reject(request.error);
            });
        }
        catch (error) {
            console.error('Cache clear error:', error);
        }
    }
    /**
     * Delete expired entries
     */
    async deleteExpired() {
        try {
            const db = await this.openDB();
            const tx = db.transaction(this.storeName, 'readwrite');
            const store = tx.objectStore(this.storeName);
            const index = store.index('expiresAt');
            const now = Date.now();
            let deletedCount = 0;
            return new Promise((resolve, reject) => {
                const request = index.openCursor(IDBKeyRange.upperBound(now));
                request.onsuccess = (event) => {
                    const cursor = event.target.result;
                    if (cursor) {
                        cursor.delete();
                        deletedCount++;
                        cursor.continue();
                    }
                    else {
                        resolve(deletedCount);
                    }
                };
                request.onerror = () => reject(request.error);
            });
        }
        catch (error) {
            console.error('Delete expired error:', error);
            return 0;
        }
    }
    /**
     * Ensure we have enough space by deleting oldest entries
     */
    async ensureSpace(needed) {
        const stats = await this.getStats();
        if (stats.totalSize + needed <= this.maxSize) {
            return; // We have enough space
        }
        // Need to free up space - delete oldest entries (LRU)
        const db = await this.openDB();
        const tx = db.transaction(this.storeName, 'readwrite');
        const store = tx.objectStore(this.storeName);
        const index = store.index('timestamp');
        let freedSpace = 0;
        return new Promise((resolve, reject) => {
            const request = index.openCursor();
            request.onsuccess = (event) => {
                const cursor = event.target.result;
                if (cursor && freedSpace < needed) {
                    const entry = cursor.value;
                    freedSpace += entry.size;
                    cursor.delete();
                    cursor.continue();
                }
                else {
                    resolve();
                }
            };
            request.onerror = () => reject(request.error);
        });
    }
    /**
     * Get cache statistics
     */
    async getStats() {
        try {
            const db = await this.openDB();
            const tx = db.transaction(this.storeName, 'readonly');
            const store = tx.objectStore(this.storeName);
            return new Promise((resolve, reject) => {
                const request = store.getAll();
                request.onsuccess = () => {
                    const items = request.result;
                    const totalSize = items.reduce((sum, item) => sum + item.size, 0);
                    const itemCount = items.length;
                    const oldestItem = items.length > 0
                        ? Math.min(...items.map(item => item.timestamp))
                        : 0;
                    const totalRequests = this.stats.hits + this.stats.misses;
                    const hitRate = totalRequests > 0
                        ? (this.stats.hits / totalRequests) * 100
                        : 0;
                    resolve({
                        totalSize,
                        itemCount,
                        hitRate,
                        oldestItem,
                    });
                };
                request.onerror = () => reject(request.error);
            });
        }
        catch (error) {
            console.error('Get stats error:', error);
            return {
                totalSize: 0,
                itemCount: 0,
                hitRate: 0,
                oldestItem: 0,
            };
        }
    }
    /**
     * Generate cache key for marine data
     */
    getMarineKey(lat, lon, date) {
        const dateStr = date ? date.toISOString().split('T')[0] : 'current';
        return `marine:${lat.toFixed(4)}:${lon.toFixed(4)}:${dateStr}`;
    }
    /**
     * Generate cache key for forecast data
     */
    getForecastKey(lat, lon, model, date) {
        const dateStr = date ? date.toISOString().split('T')[0] : 'current';
        return `forecast:${lat.toFixed(4)}:${lon.toFixed(4)}:${model}:${dateStr}`;
    }
    /**
     * Generate cache key for current conditions
     */
    getCurrentKey(lat, lon) {
        return `current:${lat.toFixed(4)}:${lon.toFixed(4)}`;
    }
    /**
     * Get TTL for data type
     */
    getTTL(type) {
        return this.TTL[type];
    }
}
// Export singleton instance
export const cacheService = new WeatherCacheService();
